    protected byte[] serializeBytes() {
        writeFrameType();
        writeStreamId();
        // Offline repair: the OFF/LEN bits of the frame type decide which optional fields exist.
        long type = frame.getFrameType().getValue();
        if ((type & STREAM_OFF_BIT) != 0) {
            writeOffset();
        }
        if ((type & STREAM_LEN_BIT) != 0) {
            writeLength();
        }
        writeData();
        return getAlreadySerialized();
    }
